def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    food_patches = image_patch.find("food")
    wood_patches = image_patch.find("wood")

    if not food_patches or not wood_patches:
        return image_patch

    wood_center_y = sum(w.vertical_center for w in wood_patches) / len(wood_patches)

    lowest_food = min(food_patches, key=lambda f: f.vertical_center)
    closest_food = min(food_patches, key=lambda f: abs(f.vertical_center - wood_center_y))

    if lowest_food == closest_food:
        return lowest_food

    if lowest_food.vertical_center < closest_food.vertical_center:
        return lowest_food
    else:
        return closest_food

